create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'subscriber' check(role in ('subscriber','admin')),subscription_status text not null default 'inactive' check(subscription_status in ('active','inactive','past_due')),renewal_date timestamptz,charity_id uuid, charity_percent integer not null default 10 check(charity_percent between 10 and 100),created_at timestamptz not null default now());
create table if not exists public.charities(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text not null,image_url text,events text,featured boolean not null default false,created_at timestamptz not null default now());
alter table public.profiles add constraint profiles_charity_fk foreign key(charity_id) references public.charities(id) on delete set null;
create table if not exists public.scores(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,score integer not null check(score between 1 and 45),score_date date not null,created_at timestamptz not null default now(),unique(user_id,score_date));
create table if not exists public.draws(id uuid primary key default gen_random_uuid(),draw_month text not null,draw_numbers integer[] not null,draw_type text not null default 'random' check(draw_type in ('random','algorithmic')),status text not null default 'draft' check(status in ('draft','published')),prize_pool numeric not null default 0,jackpot_rollover numeric not null default 0,created_at timestamptz not null default now());
create table if not exists public.winners(id uuid primary key default gen_random_uuid(),draw_id uuid references public.draws(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,tier integer not null check(tier in (3,4,5)),amount numeric not null default 0,proof_url text,verification_status text not null default 'pending' check(verification_status in ('pending','approved','rejected')),payment_status text not null default 'pending' check(payment_status in ('pending','paid')),created_at timestamptz not null default now());
insert into public.charities(name,slug,description,events,featured) values ('Green Steps Foundation','green-steps','Restoring urban green spaces and community gardens.','City Golf Day · 18 Oct',true),('Bright Futures Trust','bright-futures','Helping young people access digital learning and mentoring.','Charity Open · 02 Nov',true),('Water for Tomorrow','water-for-tomorrow','Funding clean-water projects in communities that need them most.','Impact Day · 22 Nov',false) on conflict(slug) do nothing;
create or replace function public.is_admin() returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,charity_id,charity_percent) values(new.id,new.raw_user_meta_data->>'full_name',nullif(new.raw_user_meta_data->>'charity_id','')::uuid,coalesce(nullif(new.raw_user_meta_data->>'charity_percent','')::int,10)); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.charities enable row level security; alter table public.scores enable row level security; alter table public.draws enable row level security; alter table public.winners enable row level security;
drop policy if exists profiles_self on public.profiles; create policy profiles_self on public.profiles for all using(auth.uid()=id or public.is_admin()) with check(auth.uid()=id or public.is_admin());
drop policy if exists charities_public_read on public.charities; create policy charities_public_read on public.charities for select using(true); drop policy if exists charities_admin_write on public.charities; create policy charities_admin_write on public.charities for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists scores_self on public.scores; create policy scores_self on public.scores for all using(auth.uid()=user_id or public.is_admin()) with check(auth.uid()=user_id or public.is_admin());
drop policy if exists draws_read on public.draws; create policy draws_read on public.draws for select using(status='published' or public.is_admin()); drop policy if exists draws_admin_write on public.draws; create policy draws_admin_write on public.draws for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists winners_self on public.winners; create policy winners_self on public.winners for select using(auth.uid()=user_id or public.is_admin()); drop policy if exists winners_admin_write on public.winners; create policy winners_admin_write on public.winners for all using(public.is_admin()) with check(public.is_admin());
